const http=require('http');
const {URL}=require('url');
const PORT=process.env.PORT||10000;
const OPENAI_KEY=process.env.OPENAI_API_KEY||'';
const OPENAI_MODEL=process.env.OPENAI_MODEL||'gpt-5.6-sol';
const SUPABASE_URL=process.env.SUPABASE_URL||'';
const SUPABASE_PUBLISHABLE_KEY=process.env.SUPABASE_PUBLISHABLE_KEY||'';
const SUPABASE_SECRET_KEY=process.env.SUPABASE_SECRET_KEY||'';
const HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>HAJREEN — CEO Business OS</title>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n<style>\n:root{--bg:#07090b;--panel:#0d1114;--panel2:#11161a;--line:#222a30;--text:#f5f6f7;--muted:#8c969e;--gold:#c9a55b;--gold2:#e4c47b;--danger:#e26b73;--ok:#6ed08a;--blue:#77a9ff;--shadow:0 18px 50px rgba(0,0,0,.35)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,rgba(201,165,91,.10),transparent 32%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.hidden{display:none!important}.shell{min-height:100vh}.top{height:70px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:16px;padding:0 22px;position:sticky;top:0;background:rgba(7,9,11,.94);backdrop-filter:blur(18px);z-index:30}.brand{font-weight:800;letter-spacing:.25em}.brand small{display:block;color:var(--muted);font-size:10px;letter-spacing:.18em;margin-top:2px}.top-spacer{flex:1}.pill{border:1px solid var(--line);border-radius:999px;padding:8px 12px;color:var(--muted);font-size:12px}.btn{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:10px;padding:10px 14px}.btn:hover{border-color:#3a444c}.btn.gold{background:linear-gradient(135deg,#d2ad61,#a9833c);color:#0a0a0a;border:0;font-weight:800}.btn.danger{border-color:#5b252a;color:#ff9ca1}.layout{display:grid;grid-template-columns:240px 1fr;min-height:calc(100vh - 70px)}.side{border-right:1px solid var(--line);padding:18px 12px;background:#090c0f}.nav{display:flex;flex-direction:column;gap:4px}.nav button{border:0;background:transparent;color:#aab2b8;text-align:left;padding:12px 14px;border-radius:10px}.nav button.active,.nav button:hover{background:#151a1f;color:#fff}.nav button.active{box-shadow:inset 2px 0 var(--gold);color:#fff}.content{padding:26px;max-width:1500px;width:100%;margin:auto}.page-title{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:22px}.page-title h1{font-size:30px;margin:0}.page-title p{margin:6px 0 0;color:var(--muted)}.grid{display:grid;gap:14px}.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.g3{grid-template-columns:repeat(3,minmax(0,1fr))}.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.card{background:linear-gradient(145deg,rgba(17,22,26,.95),rgba(10,13,16,.95));border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:var(--shadow)}.metric label{display:block;color:#879198;font-size:11px;letter-spacing:.16em;text-transform:uppercase}.metric strong{display:block;font-size:27px;margin:10px 0 4px}.metric span{color:var(--muted);font-size:12px}.section{margin-top:18px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.section-head h2{font-size:16px;margin:0}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px}.table{width:100%;border-collapse:collapse;min-width:700px}.table th,.table td{padding:12px 13px;border-bottom:1px solid #1d2429;text-align:left;font-size:13px}.table th{color:#89939a;font-size:10px;letter-spacing:.13em;text-transform:uppercase}.table tr:last-child td{border-bottom:0}.tag{display:inline-flex;padding:5px 8px;border-radius:999px;background:#161d22;color:#b7c0c5;font-size:11px}.tag.ok{color:#9ae3ac;background:#0f2116}.tag.warn{color:#f0d28c;background:#231e10}.tag.danger{color:#ff9ca1;background:#251215}.bar{height:8px;background:#171d21;border-radius:999px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#8c6d32,#e4c47b);border-radius:999px}.form{display:grid;gap:12px}.form.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.field{display:grid;gap:6px}.field label{font-size:11px;color:#929ba2;text-transform:uppercase;letter-spacing:.12em}.field input,.field select,.field textarea{width:100%;background:#090d10;border:1px solid #2a333a;color:#fff;border-radius:10px;padding:11px 12px;outline:none}.field textarea{min-height:90px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:#8e713c}.actions{display:flex;gap:8px;flex-wrap:wrap}.modal{position:fixed;inset:0;background:rgba(0,0,0,.75);backdrop-filter:blur(8px);display:grid;place-items:center;padding:18px;z-index:100}.modal-box{width:min(760px,100%);max-height:90vh;overflow:auto;background:#0d1114;border:1px solid #303a42;border-radius:18px;padding:20px}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.modal-head h3{margin:0}.close{background:transparent;border:0;color:#aaa;font-size:24px}.login{min-height:100vh;display:grid;place-items:center;padding:20px}.login-box{width:min(460px,100%);background:linear-gradient(145deg,#11161a,#090c0f);border:1px solid #293138;border-radius:22px;padding:28px;box-shadow:var(--shadow)}.logo-mark{display:none!important}.login h1{margin:0 0 7px;font-size:28px}.login p{color:var(--muted);line-height:1.5}.login-tabs{display:flex;gap:4px;background:#090d10;border:1px solid var(--line);padding:4px;border-radius:10px;margin:18px 0}.login-tabs button{flex:1;background:transparent;border:0;color:#8f989e;padding:9px;border-radius:8px}.login-tabs button.active{background:#1a2025;color:#fff}.password{position:relative}.password input{padding-right:48px}.eye{position:absolute;right:5px;top:5px;height:38px;width:38px;background:transparent;border:0;color:#8e989f}.ai{display:grid;grid-template-columns:1fr 330px;gap:16px}.ai-main{min-height:520px;display:flex;flex-direction:column}.ai-log{flex:1;overflow:auto;display:flex;flex-direction:column;gap:10px;margin-bottom:12px}.msg{max-width:92%;padding:13px 15px;border-radius:13px;line-height:1.5;white-space:pre-wrap}.msg.user{align-self:flex-end;background:#1a2025}.msg.ai{align-self:flex-start;background:#10171b;border:1px solid #263138}.ai-input{display:flex;gap:8px}.ai-input textarea{flex:1;background:#090d10;border:1px solid #2a333a;color:#fff;border-radius:12px;padding:12px;min-height:55px}.mobile-nav{display:none}.chart{height:150px;display:flex;align-items:end;gap:7px}.chart span{flex:1;background:linear-gradient(to top,#72582b,#d7b86e);border-radius:5px 5px 0 0;min-width:8px}.alert{padding:12px;border:1px solid #332c1d;background:#16140f;border-radius:11px;margin-bottom:8px}.alert.danger{border-color:#4b2227;background:#171013}.alert.ok{border-color:#21452c;background:#0e1711}.empty{color:#727c83;padding:25px;text-align:center}.muted{color:var(--muted)}.toast{position:fixed;right:16px;bottom:20px;background:#141a1e;border:1px solid #354048;padding:12px 15px;border-radius:10px;z-index:200;box-shadow:var(--shadow)}@media(max-width:980px){.layout{grid-template-columns:1fr}.side{display:none}.content{padding:18px 14px 90px}.g4{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:1fr 1fr}.ai{grid-template-columns:1fr}.mobile-nav{display:flex;position:fixed;bottom:0;left:0;right:0;height:68px;background:rgba(8,10,12,.96);border-top:1px solid var(--line);z-index:40}.mobile-nav button{flex:1;background:transparent;border:0;color:#778187;font-size:10px}.mobile-nav button.active{color:#fff}.top{padding:0 14px}.top .btn{padding:8px}.brand{font-size:13px}}@media(max-width:600px){.g4,.g3,.g2,.form.g2{grid-template-columns:1fr}.page-title h1{font-size:25px}.metric strong{font-size:24px}.card{padding:15px}}\n\n/* HAJREEN COMPACT LUXURY INNER PAGES */\n.content:not(.dashboard) .card{padding:13px;border-radius:13px}\n.table th,.table td{padding:8px 10px;font-size:12px}.table th{font-size:9px}\n.metric strong{font-size:23px;margin:7px 0 3px}.section{margin-top:12px}.page-title{margin-bottom:14px}.page-title h1{font-size:27px}\n.field input,.field select,.field textarea{padding:9px 10px;border-radius:9px}.modal-box{padding:16px;border-radius:15px}\n.login{background:radial-gradient(circle at 20% 20%,rgba(201,165,91,.12),transparent 35%),radial-gradient(circle at 85% 80%,rgba(61,118,255,.08),transparent 30%),#050607}\n.login-box{background:linear-gradient(145deg,rgba(20,22,24,.97),rgba(7,9,11,.98));border-color:#4b3b20;box-shadow:0 30px 90px rgba(0,0,0,.6),0 0 50px rgba(201,165,91,.07)}\n.login-box:before{content:'SECURE CEO ACCESS';display:block;color:#77a9ff;font-size:9px;letter-spacing:.22em;margin-bottom:10px}.login-box .btn.gold{box-shadow:0 8px 24px rgba(201,165,91,.16)}\n.message-filters{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.message-list{display:grid;gap:9px}\n.message-card{display:flex;gap:12px;padding:13px;border:1px solid #2a3339;border-radius:13px;background:linear-gradient(145deg,rgba(17,22,26,.96),rgba(9,12,15,.96));box-shadow:0 12px 35px rgba(0,0,0,.24)}\n.message-card.read{opacity:.72}.message-icon{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;background:#17140e;border:1px solid #554322;color:var(--gold2);flex:0 0 auto}\n.message-body{min-width:0;flex:1}.message-top{display:flex;justify-content:space-between;gap:12px}.message-top h3{font-size:14px;margin:7px 0 4px}.message-body p{margin:3px 0 7px;color:#d7dcdf;font-size:13px}.message-meta{font-size:11px;color:#8c969e;margin-bottom:8px}\n.msg-badge{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 5px;border-radius:99px;background:#8f252f;color:#fff;font-size:9px;margin-left:4px}\n.message-card .btn{padding:7px 10px;font-size:11px}.secure-blue{color:#77a9ff}.sale-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:2px 0 4px}.sale-summary .mini{padding:9px 10px;border:1px solid #273039;border-radius:10px;background:#0a0e11}.sale-summary small{display:block;color:#8d979e;font-size:9px;text-transform:uppercase;letter-spacing:.12em}.sale-summary b{display:block;margin-top:4px;font-size:14px}.security-list{display:grid;gap:8px}.security-row{display:flex;justify-content:space-between;gap:12px;padding:10px 12px;border:1px solid #252e35;border-radius:10px;background:#0a0e11}\n@media(max-width:600px){.content:not(.dashboard) .card{padding:11px}.table th,.table td{padding:7px 8px;font-size:11px}.message-card{padding:11px}.message-top{display:block}.message-top>.muted{display:block;margin-top:4px}.page-title h1{font-size:23px}.sale-summary{grid-template-columns:1fr 1fr}.sale-summary .mini:last-child{grid-column:1/-1}}\n</style></head>\n<body>\n<div id=\"loginView\" class=\"login\"><div class=\"login-box\"><h1>HAJREEN</h1><p>Executive Business Operating System — cash, sales, stock, customers, credit, wholesale and AI intelligence.</p><div class=\"login-tabs\"><button id=\"tabLogin\" class=\"active\" onclick=\"setAuthMode('login')\">Sign in</button><button id=\"tabSignup\" onclick=\"setAuthMode('signup')\">Create account</button></div><div class=\"form\"><div class=\"field\"><label>Email</label><input id=\"authEmail\" type=\"email\" autocomplete=\"email\" placeholder=\"you@example.com\"></div><div class=\"field\"><label>Password</label><div class=\"password\"><input id=\"authPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Password\"><button class=\"eye\" onclick=\"togglePassword()\" type=\"button\">◉</button></div></div><div class=\"actions\"><label class=\"muted\" style=\"font-size:12px\"><input id=\"remember\" type=\"checkbox\" checked> Remember session</label><button class=\"btn\" type=\"button\" onclick=\"resetPassword()\">Forgot password?</button></div><button class=\"btn gold\" onclick=\"submitAuth()\" id=\"authBtn\">Sign in</button><div id=\"authMsg\" class=\"muted\"></div></div></div></div>\n<div id=\"app\" class=\"shell hidden\"><header class=\"top\"><div class=\"brand\">HAJREEN<small>CEO BUSINESS OS</small></div><div class=\"top-spacer\"></div><span id=\"cloudPill\" class=\"pill\">OFFLINE</span><button class=\"btn message-top-btn\" onclick=\"go('messages')\">◉ <span id=\"topMsgCount\">0</span></button><button class=\"btn\" onclick=\"openModal('quickModal')\">+ New</button><button class=\"btn\" onclick=\"logout()\">Logout</button></header><div class=\"layout\"><aside class=\"side\"><nav id=\"sideNav\" class=\"nav\"></nav></aside><main id=\"main\" class=\"content\"></main></div><nav id=\"mobileNav\" class=\"mobile-nav\"></nav></div>\n<div id=\"quickModal\" class=\"modal hidden\"><div class=\"modal-box\"><div class=\"modal-head\"><h3>Quick action</h3><button class=\"close\" onclick=\"closeModal('quickModal')\">×</button></div><div class=\"grid g2\"><button class=\"btn\" onclick=\"closeModal('quickModal');openSale()\">Record Sale</button><button class=\"btn\" onclick=\"closeModal('quickModal');openPayment()\">Record Payment</button><button class=\"btn\" onclick=\"closeModal('quickModal');openProduct()\">Add Product</button><button class=\"btn\" onclick=\"closeModal('quickModal');openCustomer()\">Add Customer</button><button class=\"btn\" onclick=\"closeModal('quickModal');openExpense()\">Add Expense</button><button class=\"btn\" onclick=\"closeModal('quickModal');go('ai')\">Ask AI CEO</button><button class=\"btn\" onclick=\"closeModal('quickModal');go('messages')\">Messages</button></div></div></div>\n<div id=\"formModal\" class=\"modal hidden\"><div class=\"modal-box\"><div class=\"modal-head\"><h3 id=\"modalTitle\">Form</h3><button class=\"close\" onclick=\"closeModal('formModal')\">×</button></div><div id=\"modalBody\"></div></div></div>\n<div id=\"toast\" class=\"toast hidden\"></div>\n<script>\nconst stateKey='hajreen_v16_state';\nconst EMPTY={sales:[],products:[],customers:[],payments:[],expenses:[],leads:[],wholesale:[],marketing:[],tasks:[],employees:[],tickets:[],stockMovements:[],activity:[],messages:[],settings:{currency:'TZS',businessName:'HAJREEN',customerPulse:true,messageAlerts:true,timezone:'Africa/Dar_es_Salaam'}};\nlet data=loadLocal(), sb=null, session=null, authMode='login', page='home', cloudReady=false;\nconst nav=[['home','HOME'],['sales','SALES'],['stock','STOCK'],['customers','CUSTOMERS'],['payments','PAYMENTS'],['messages','MESSAGES'],['wholesale','WHOLESALE'],['expenses','CASHFLOW'],['marketing','MARKETING'],['reports','REPORTS'],['ai','HAJREEN AI'],['settings','SYSTEM']];\nfunction clone(o){return JSON.parse(JSON.stringify(o))} function normalizeData(raw){const base=clone(EMPTY);if(!raw||typeof raw!=='object'||Array.isArray(raw))return base;for(const k of Object.keys(base)){if(Array.isArray(base[k]))base[k]=Array.isArray(raw[k])?raw[k]:[];else if(base[k]&&typeof base[k]==='object')base[k]={...base[k],...(raw[k]&&typeof raw[k]==='object'&&!Array.isArray(raw[k])?raw[k]:{})}}return base} function loadLocal(){try{return normalizeData(JSON.parse(localStorage.getItem(stateKey)||'{}'))}catch{return clone(EMPTY)}}\nfunction saveLocal(){localStorage.setItem(stateKey,JSON.stringify(data))} function sum(a,fn){return (a||[]).reduce((x,y)=>x+Number(fn(y)||0),0)}  function money(n){return 'TSh '+Number(n||0).toLocaleString('en-TZ')} function uid(p='id'){return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)} function esc(s){return String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction today(){return new Date().toISOString().slice(0,10)}\nfunction nowTZ(){return new Date().toLocaleString('en-GB',{timeZone:'Africa/Dar_es_Salaam',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).replace(',', ' ·')}\nfunction fmtDateTime(x){if(!x)return '—';const d=new Date(x);if(Number.isNaN(d.getTime()))return String(x);return d.toLocaleString('en-GB',{timeZone:'Africa/Dar_es_Salaam',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).replace(',', ' ·')}\nfunction daysBetween(a,b=new Date()){const d=new Date(a);return Number.isNaN(d.getTime())?0:Math.max(0,Math.floor((new Date(b)-d)/86400000))}\nfunction customerPulse(){\n  if(data.settings?.customerPulse===false)return [];\n  const msgs=[],now=new Date();\n  (data.customers||[]).forEach(c=>{\n    const orders=data.sales.filter(s=>s.customerId===c.id).sort((a,b)=>new Date(a.createdAt||a.date)-new Date(b.createdAt||b.date));\n    if(orders.length<2)return;\n    const gaps=[];for(let i=1;i<orders.length;i++)gaps.push(daysBetween(orders[i-1].createdAt||orders[i-1].date,orders[i].createdAt||orders[i].date));\n    const avg=Math.max(1,Math.round(sum(gaps,x=>x)/gaps.length));\n    const last=orders[orders.length-1].createdAt||orders[orders.length-1].date;\n    const silent=daysBetween(last,now);\n    let status='Active';if(silent>avg*2)status='Dormant';else if(silent>avg*1.5)status='At Risk';else if(silent>avg)status='Due for Follow-up';\n    if(status!=='Active'){\n      const key='pulse_'+c.id+'_'+last+'_'+status;\n      if(!(data.messages||[]).some(m=>m.key===key))msgs.push({id:uid('msg'),key,type:'Customer Follow-up',category:'Customers',title:'Customer Follow-up',customerId:c.id,customerName:c.name,body:`Hajafanya order kwa siku ${silent}. Kwa kawaida hufanya orders kila ${avg} days.`,lastOrder:last,usualDays:avg,daysSilent:silent,status,read:false,createdAt:now.toISOString(),action:'followup'});\n    }\n  });\n  if(msgs.length&&data.settings?.messageAlerts!==false){data.messages.push(...msgs);saveLocal()}\n  return msgs;\n}\nfunction businessAlerts(){\n  if(data.settings?.messageAlerts===false)return [];\n  const msgs=[],now=new Date(),todayKey=today();\n  (data.products||[]).forEach(p=>{\n    const qty=Number(p.qty||0),low=Number(p.low||3);\n    if(qty<=low){const level=qty===0?'Out of Stock':'Low Stock',key=`stock_${p.id}_${qty}_${level}`;if(!data.messages.some(m=>m.key===key))msgs.push({id:uid('msg'),key,type:level,category:'Stock',title:`${level}: ${p.name}`,body:qty===0?`${p.name} imekwisha kabisa.`:`${p.name} imebaki ${qty} unit(s), chini ya threshold ya ${low}.`,productId:p.id,read:false,createdAt:now.toISOString()})}\n  });\n  (data.sales||[]).forEach(s=>{\n    const paid=sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount),bal=Math.max(0,Number(s.total)-paid);\n    if(bal>0&&s.dueDate&&s.dueDate<todayKey){const key=`overdue_${s.id}_${bal}_${s.dueDate}`;if(!data.messages.some(m=>m.key===key))msgs.push({id:uid('msg'),key,type:'Payment Reminder',category:'Payments',title:'Overdue Credit',customerId:s.customerId,body:`Order ${s.orderNo||s.id} ina balance ya ${money(bal)} na due date ${s.dueDate}.`,read:false,createdAt:now.toISOString()})}\n  });\n  (data.wholesale||[]).forEach(w=>{\n    if(w.followUp&&w.followUp<=todayKey&&w.stage!=='Won'&&w.stage!=='Lost'){const key=`wholesale_${w.id}_${w.followUp}_${w.stage}`;if(!data.messages.some(m=>m.key===key))msgs.push({id:uid('msg'),key,type:'Wholesale Follow-up',category:'Wholesale',title:`Wholesale Follow-up: ${w.name}`,body:`Follow-up ya wholesale opportunity hii imefika tarehe ${w.followUp}. Stage: ${w.stage}.`,read:false,createdAt:now.toISOString()})}\n  });\n  if(msgs.length){data.messages.push(...msgs);saveLocal()}\n  return msgs;\n}\nfunction refreshBusinessMessages(){customerPulse();businessAlerts()}\nfunction messageCount(){customerPulse();return (data.messages||[]).filter(m=>!m.read).length}\nfunction calc(){const revenue=sum(data.sales,s=>s.total);const cogs=sum(data.sales,s=>s.costTotal);const gross=revenue-cogs;const exp=sum(data.expenses,e=>e.amount);const paid=sum(data.payments,p=>p.amount);const receivables=sum(data.sales,s=>Math.max(0,Number(s.total)-sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount)));const stock=sum(data.products,p=>Number(p.qty)*Number(p.cost));const overdue=sum(data.sales,s=>{const bal=Number(s.total)-sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount);return bal>0&&s.dueDate&&s.dueDate<today()?bal:0});return {revenue,cogs,gross,exp,net:gross-exp,paid,receivables,stock,overdue,orders:data.sales.length,customers:data.customers.length,low:data.products.filter(p=>Number(p.qty)<=Number(p.low||3)).length}}\nfunction toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),2800)}\nfunction navRender(){refreshBusinessMessages();const unread=messageCount();const html=nav.map(([id,label])=>`<button class=\"${page===id?'active':''}\" onclick=\"go('${id}')\">${id==='messages'?'◉ ':''}${label}${id==='messages'&&unread?` <span class=\"msg-badge\">${unread}</span>`:''}</button>`).join('');document.getElementById('sideNav').innerHTML=html;const tm=document.getElementById('topMsgCount');if(tm)tm.textContent=unread;document.getElementById('mobileNav').innerHTML=nav.slice(0,5).map(([id,label])=>`<button class=\"${page===id?'active':''}\" onclick=\"go('${id}')\">${label}</button>`).join('')}\nfunction go(p){page=p;navRender();renderPage()}\nfunction renderPage(){refreshBusinessMessages();const m=document.getElementById('main');m.className='content'+(page==='home'?' dashboard':'');const c=calc();if(page==='home')m.innerHTML=home(c);else if(page==='sales')m.innerHTML=salesPage();else if(page==='stock')m.innerHTML=stockPage();else if(page==='customers')m.innerHTML=customersPage();else if(page==='payments')m.innerHTML=paymentsPage();else if(page==='messages')m.innerHTML=messagesPage();else if(page==='wholesale')m.innerHTML=wholesalePage();else if(page==='expenses')m.innerHTML=expensesPage();else if(page==='marketing')m.innerHTML=marketingPage();else if(page==='reports')m.innerHTML=reportsPage();else if(page==='ai')m.innerHTML=aiPage();else m.innerHTML=settingsPage();}\nfunction home(c){const alerts=[];if(c.low)alerts.push(`<div class=\"alert\">${c.low} product(s) at or below low-stock threshold.</div>`);if(c.overdue)alerts.push(`<div class=\"alert danger\">Overdue receivables: <b>${money(c.overdue)}</b></div>`);if(!alerts.length)alerts.push('<div class=\"alert ok\">No critical business alerts from the current dataset.</div>');const bars=Array.from({length:12},(_,i)=>`<span style=\"height:${12+Math.min(82,((i+1)/(12))*65)}%\"></span>`).join('');return `<div class=\"page-title\"><div><h1>Good morning, CEO.</h1><p>Decision-first control of cash, growth, inventory and execution.</p></div><span class=\"pill\">${cloudReady?'CLOUD CONNECTED':'LOCAL MODE'}</span></div><div class=\"grid g4\"><div class=\"card metric\"><label>Revenue</label><strong>${money(c.revenue)}</strong><span>${c.orders} orders tracked</span></div><div class=\"card metric\"><label>Gross Profit</label><strong>${money(c.gross)}</strong><span>Before expenses</span></div><div class=\"card metric\"><label>Net Profit</label><strong>${money(c.net)}</strong><span>After expenses</span></div><div class=\"card metric\"><label>Receivables</label><strong>${money(c.receivables)}</strong><span>${money(c.overdue)} overdue</span></div><div class=\"card metric\"><label>Cash Received</label><strong>${money(c.paid)}</strong><span>All payment methods</span></div><div class=\"card metric\"><label>Inventory Value</label><strong>${money(c.stock)}</strong><span>${c.low} low-stock items</span></div><div class=\"card metric\"><label>Customers</label><strong>${c.customers}</strong><span>Customer profiles</span></div><div class=\"card metric\"><label>Wholesale Pipeline</label><strong>${money(sum(data.wholesale,w=>w.expected||0))}</strong><span>${data.wholesale.length} opportunities</span></div></div><div class=\"grid g2 section\"><div class=\"card\"><div class=\"section-head\"><h2>Growth Engine</h2><span class=\"tag\">LIVE DATA</span></div><div class=\"chart\">${bars}</div><p class=\"muted\">Visual trend placeholder becomes data-driven as sales accumulate.</p></div><div class=\"card\"><div class=\"section-head\"><h2>CEO Alerts</h2><button class=\"btn\" onclick=\"go('reports')\">Open reports</button></div>${alerts.join('')}</div></div>`}\nfunction salesPage(){return `<div class=\"page-title\"><div><h1>Sales</h1><p>Orders, profit, payments and customer balances.</p></div><button class=\"btn gold\" onclick=\"openSale()\">+ Record sale</button></div><div class=\"card\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Date</th><th>Order</th><th>Customer</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${data.sales.length?data.sales.slice().reverse().map(s=>{const paid=sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount),bal=Number(s.total)-paid;return `<tr><td>${fmtDateTime(s.createdAt||s.date)}</td><td>${esc(s.orderNo)}</td><td>${esc(customerName(s.customerId))}</td><td>${money(s.total)}</td><td>${money(paid)}</td><td>${money(Math.max(0,bal))}</td><td><span class=\"tag ${bal<=0?'ok':(s.dueDate&&s.dueDate<today()?'danger':'warn')}\">${bal<=0?'PAID':(s.dueDate&&s.dueDate<today()?'OVERDUE':'CREDIT')}</span></td><td><button class=\"btn\" onclick=\"openPayment('${s.id}')\">Payment</button></td></tr>`}).join(''):'<tr><td colspan=\"8\" class=\"empty\">No sales recorded yet.</td></tr>'}</tbody></table></div></div>`}\nfunction stockPage(){const low=data.products.filter(p=>Number(p.qty)<=Number(p.low||3)).length;return `<div class=\"page-title\"><div><h1>Inventory</h1><p>Stock levels, pricing, movement and low-stock control.</p></div><button class=\"btn gold\" onclick=\"openProduct()\">+ Add product</button></div><div class=\"grid g3\"><div class=\"card metric\"><label>Inventory Value</label><strong>${money(sum(data.products,p=>p.qty*p.cost))}</strong></div><div class=\"card metric\"><label>Units</label><strong>${sum(data.products,p=>p.qty)}</strong></div><div class=\"card metric\"><label>Low Stock</label><strong>${low}</strong></div></div><div class=\"card section\"><div class=\"section-head\"><h2>Products</h2><span class=\"tag\">${data.products.length} items</span></div><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>Qty</th><th>Cost</th><th>Selling</th><th>Wholesale</th><th>Status</th><th></th></tr></thead><tbody>${data.products.length?data.products.map(p=>`<tr><td>${esc(p.sku)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td>${p.qty}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${money(p.wholesale)}</td><td><span class=\"tag ${Number(p.qty)===0?'danger':Number(p.qty)<=Number(p.low||3)?'warn':'ok'}\">${Number(p.qty)===0?'OUT':Number(p.qty)<=Number(p.low||3)?'LOW':'OK'}</span></td><td><button class=\"btn\" onclick=\"editProduct('${p.id}')\">Edit</button></td></tr>`).join(''):'<tr><td colspan=\"9\" class=\"empty\">No products yet.</td></tr>'}</tbody></table></div></div><div class=\"card section\"><div class=\"section-head\"><h2>Stock Movement</h2><span class=\"muted\">date · month · year · time</span></div><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Time</th><th>Product</th><th>Type</th><th>Qty</th></tr></thead><tbody>${data.stockMovements.slice().reverse().map(m=>`<tr><td>${fmtDateTime(m.createdAt||m.date)}</td><td>${esc(data.products.find(p=>p.id===m.productId)?.name||'—')}</td><td>${esc(m.type)}</td><td>${m.qty>0?'+':''}${m.qty}</td></tr>`).join('')||'<tr><td colspan=\"4\" class=\"empty\">No movement recorded.</td></tr>'}</tbody></table></div></div>`}\nfunction editProduct(id){const p=data.products.find(x=>x.id===id);if(!p)return;modal('Edit product',`<form class=\"form g2\" onsubmit=\"event.preventDefault();saveProductEdit('${id}')\"><div class=\"field\"><label>Product name</label><input id=\"epName\" value=\"${esc(p.name)}\" required></div><div class=\"field\"><label>SKU</label><input id=\"epSku\" value=\"${esc(p.sku)}\" required></div><div class=\"field\"><label>Category</label><input id=\"epCat\" value=\"${esc(p.category||'')}\"></div><div class=\"field\"><label>Stock quantity</label><input id=\"epQty\" type=\"number\" min=\"0\" value=\"${p.qty}\"></div><div class=\"field\"><label>Cost price</label><input id=\"epCost\" type=\"number\" min=\"0\" value=\"${p.cost}\"></div><div class=\"field\"><label>Selling price</label><input id=\"epPrice\" type=\"number\" min=\"0\" value=\"${p.price}\"></div><div class=\"field\"><label>Wholesale price</label><input id=\"epWhole\" type=\"number\" min=\"0\" value=\"${p.wholesale}\"></div><div class=\"field\"><label>Low stock threshold</label><input id=\"epLow\" type=\"number\" min=\"0\" value=\"${p.low||3}\"></div><button class=\"btn gold\">Save changes</button></form>`)}\nfunction saveProductEdit(id){const p=data.products.find(x=>x.id===id);if(!p)return;const old=p.qty;p.name=v('epName');p.sku=v('epSku');p.category=v('epCat');p.qty=+v('epQty');p.cost=+v('epCost');p.price=+v('epPrice');p.wholesale=+v('epWhole');p.low=+v('epLow');if(old!==p.qty)data.stockMovements.push({id:uid('mov'),productId:p.id,type:'ADJUSTMENT',qty:p.qty-old,createdAt:new Date().toISOString()});commit('Product updated');closeModal('formModal')}\n\nfunction customersPage(){customerPulse();return `<div class=\"page-title\"><div><h1>Customer 360</h1><p>Profiles, orders, payments, balances and behavior-based follow-up.</p></div><button class=\"btn gold\" onclick=\"openCustomer()\">+ Add customer</button></div><div class=\"grid g4\"><div class=\"card metric\"><label>Customers</label><strong>${data.customers.length}</strong></div><div class=\"card metric\"><label>Customer Revenue</label><strong>${money(sum(data.sales,s=>s.total))}</strong></div><div class=\"card metric\"><label>Receivables</label><strong>${money(calc().receivables)}</strong></div><div class=\"card metric\"><label>Follow-up Due</label><strong>${data.messages.filter(m=>m.category==='Customers'&&!m.read).length}</strong></div></div><div class=\"card section\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Customer</th><th>Phone</th><th>Type</th><th>Orders</th><th>Total Value</th><th>Balance</th><th>Pulse</th><th></th></tr></thead><tbody>${data.customers.length?data.customers.map(c=>{const ss=data.sales.filter(s=>s.customerId===c.id),val=sum(ss,s=>s.total),bal=sum(ss,s=>Number(s.total)-sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount));const pm=data.messages.filter(m=>m.customerId===c.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return `<tr><td><b>${esc(c.name)}</b><br><span class=\"muted\">${esc(c.location||'')}</span></td><td>${esc(c.phone||'')}</td><td>${esc(c.type||'Retail')}</td><td>${ss.length}</td><td>${money(val)}</td><td>${money(Math.max(0,bal))}</td><td><span class=\"tag ${!pm?'ok':pm.status==='Dormant'||pm.status==='At Risk'?'danger':'warn'}\">${pm?esc(pm.status):'Active'}</span></td><td><button class=\"btn\" onclick=\"viewCustomer('${c.id}')\">Open 360</button></td></tr>`}).join(''):'<tr><td colspan=\"8\" class=\"empty\">No customers yet.</td></tr>'}</tbody></table></div></div>`}\nfunction paymentsPage(){const cash=sum(data.payments,p=>p.method==='Cash'?p.amount:0),bank=sum(data.payments,p=>p.method==='Bank'?p.amount:0),mobile=sum(data.payments,p=>p.method==='Mobile Money'?p.amount:0);return `<div class=\"page-title\"><div><h1>Payments & Credit</h1><p>Cash, bank, mobile money, partial payments and receivables.</p></div><button class=\"btn gold\" onclick=\"openPayment()\">+ Record payment</button></div><div class=\"grid g4\"><div class=\"card metric\"><label>Paid Today</label><strong>${money(sum(data.payments,p=>p.date===today()?p.amount:0))}</strong></div><div class=\"card metric\"><label>Cash</label><strong>${money(cash)}</strong></div><div class=\"card metric\"><label>Bank</label><strong>${money(bank)}</strong></div><div class=\"card metric\"><label>Mobile Money</label><strong>${money(mobile)}</strong></div></div><div class=\"card section\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Date</th><th>Customer</th><th>Order</th><th>Method</th><th>Amount</th><th>Reference</th><th>Received by</th></tr></thead><tbody>${data.payments.length?data.payments.slice().reverse().map(p=>`<tr><td>${fmtDateTime(p.createdAt||p.date)}</td><td>${esc(customerName(p.customerId))}</td><td>${esc(saleOrder(p.saleId))}</td><td>${esc(p.method)}${p.network?` · ${esc(p.network)}`:''}</td><td>${money(p.amount)}</td><td>${esc(p.reference||'—')}</td><td>${esc(p.receiver||'')}</td></tr>`).join(''):'<tr><td colspan=\"7\" class=\"empty\">No payments recorded yet.</td></tr>'}</tbody></table></div></div>`}\nfunction messagesPage(){customerPulse();const cats=['All','Customers','Payments','Stock','Wholesale','System'];const unread=data.messages.filter(m=>!m.read).length;return `<div class=\"page-title\"><div><h1>Messages</h1><p>Business Intelligence Inbox — follow-ups, payment reminders, stock and business alerts.</p></div><div class=\"actions\"><span class=\"pill\">${unread} unread</span><button class=\"btn\" onclick=\"markAllMessagesRead()\">Mark all read</button></div></div><div class=\"message-filters\">${cats.map(c=>`<button class=\"btn ${c==='All'?'gold':''}\" onclick=\"filterMessages('${c}')\">${c}</button>`).join('')}</div><div id=\"messageList\" class=\"message-list\">${renderMessages('All')}</div>`}\nfunction renderMessages(filter='All'){const rows=data.messages.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).filter(m=>filter==='All'||m.category===filter);if(!rows.length)return '<div class=\"card empty\">No messages right now.</div>';return rows.map(m=>`<div class=\"message-card ${m.read?'read':''}\"><div class=\"message-icon\">${m.category==='Customers'?'◉':m.category==='Payments'?'₵':m.category==='Stock'?'▦':m.category==='Wholesale'?'W':'!'}</div><div class=\"message-body\"><div class=\"message-top\"><div><span class=\"tag ${m.status==='At Risk'||m.status==='Dormant'?'danger':m.status==='Due for Follow-up'?'warn':'ok'}\">${esc(m.type||m.category)}</span><h3>${esc(m.title)}</h3></div><span class=\"muted\">${fmtDateTime(m.createdAt)}</span></div><p>${esc(m.body)}</p>${m.lastOrder?`<div class=\"message-meta\">Last order: <b>${fmtDateTime(m.lastOrder)}</b> · Usual interval: <b>${m.usualDays} days</b> · Silent: <b>${m.daysSilent} days</b></div>`:''}<div class=\"actions\">${m.customerId?`<button class=\"btn gold\" onclick=\"messageCustomer('${m.id}','${m.customerId}')\">View Customer</button><button class=\"btn\" onclick=\"followUpCustomer('${m.id}','${m.customerId}')\">Follow Up</button>`:''}<button class=\"btn\" onclick=\"toggleMessage('${m.id}')\">${m.read?'Mark unread':'Mark read'}</button></div></div></div>`).join('')}\nfunction filterMessages(f){document.querySelectorAll('.message-filters .btn').forEach(b=>b.classList.remove('gold'));[...document.querySelectorAll('.message-filters .btn')].find(b=>b.textContent===f)?.classList.add('gold');document.getElementById('messageList').innerHTML=renderMessages(f)}\nfunction toggleMessage(id){const m=data.messages.find(x=>x.id===id);if(m)m.read=!m.read;saveLocal();navRender();renderPage()}\nfunction markAllMessagesRead(){data.messages.forEach(m=>m.read=true);commit('Messages marked read')}\nfunction messageCustomer(mid,cid){const m=data.messages.find(x=>x.id===mid);if(m){m.read=true;saveLocal()}viewCustomer(cid)}\nfunction followUpCustomer(mid,cid){const m=data.messages.find(x=>x.id===mid);if(m){m.read=true;saveLocal()}viewCustomer(cid);toast('Customer opened for follow-up')}\n\nfunction wholesalePage(){return `<div class=\"page-title\"><div><h1>Wholesale Pipeline</h1><p>Lead value, follow-ups, conversion and expected orders.</p></div><button class=\"btn gold\" onclick=\"openWholesale()\">+ Add opportunity</button></div><div class=\"grid g3\"><div class=\"card metric\"><label>Pipeline Value</label><strong>${money(sum(data.wholesale,w=>w.expected))}</strong></div><div class=\"card metric\"><label>Open Opportunities</label><strong>${data.wholesale.filter(w=>w.stage!=='Won').length}</strong></div><div class=\"card metric\"><label>Won Value</label><strong>${money(sum(data.wholesale.filter(w=>w.stage==='Won'),w=>w.expected))}</strong></div></div><div class=\"card section\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Business</th><th>Contact</th><th>Stage</th><th>Expected</th><th>Follow-up</th><th>Notes</th></tr></thead><tbody>${data.wholesale.length?data.wholesale.map(w=>`<tr><td><b>${esc(w.name)}</b></td><td>${esc(w.phone||'')}</td><td><span class=\"tag\">${esc(w.stage)}</span></td><td>${money(w.expected)}</td><td>${esc(w.followUp||'')}</td><td>${esc(w.notes||'')}</td></tr>`).join(''):'<tr><td colspan=\"6\" class=\"empty\">No wholesale opportunities yet.</td></tr>'}</tbody></table></div></div>`}\nfunction expensesPage(){return `<div class=\"page-title\"><div><h1>Cashflow & Expenses</h1><p>Track business outflows and net operating position.</p></div><button class=\"btn gold\" onclick=\"openExpense()\">+ Add expense</button></div><div class=\"grid g3\"><div class=\"card metric\"><label>Total Expenses</label><strong>${money(sum(data.expenses,e=>e.amount))}</strong></div><div class=\"card metric\"><label>Gross Profit</label><strong>${money(calc().gross)}</strong></div><div class=\"card metric\"><label>Net Profit</label><strong>${money(calc().net)}</strong></div></div><div class=\"card section\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Date</th><th>Category</th><th>Method</th><th>Amount</th><th>Vendor</th><th>Notes</th></tr></thead><tbody>${data.expenses.length?data.expenses.slice().reverse().map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.method)}</td><td>${money(e.amount)}</td><td>${esc(e.vendor||'')}</td><td>${esc(e.notes||'')}</td></tr>`).join(''):'<tr><td colspan=\"6\" class=\"empty\">No expenses recorded yet.</td></tr>'}</tbody></table></div></div>`}\nfunction marketingPage(){return `<div class=\"page-title\"><div><h1>Marketing Intelligence</h1><p>Campaign cost, leads, attributed sales and ROI.</p></div><button class=\"btn gold\" onclick=\"openMarketing()\">+ Add campaign</button></div><div class=\"card\"><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Campaign</th><th>Channel</th><th>Spend</th><th>Leads</th><th>Sales Value</th><th>ROI</th></tr></thead><tbody>${data.marketing.length?data.marketing.map(m=>{const roi=m.spend?((m.salesValue-m.spend)/m.spend*100):0;return `<tr><td>${esc(m.name)}</td><td>${esc(m.channel)}</td><td>${money(m.spend)}</td><td>${m.leads}</td><td>${money(m.salesValue)}</td><td>${roi.toFixed(1)}%</td></tr>`}).join(''):'<tr><td colspan=\"6\" class=\"empty\">No campaigns yet.</td></tr>'}</tbody></table></div></div>`}\nfunction reportsPage(){const c=calc();const top=[...data.products].sort((a,b)=>b.qty-a.qty).slice(0,8);return `<div class=\"page-title\"><div><h1>Executive Reports</h1><p>Financial, customer, product and operational intelligence.</p></div><button class=\"btn\" onclick=\"exportBackup()\">Export backup</button></div><div class=\"grid g4\"><div class=\"card metric\"><label>Revenue</label><strong>${money(c.revenue)}</strong></div><div class=\"card metric\"><label>COGS</label><strong>${money(c.cogs)}</strong></div><div class=\"card metric\"><label>Gross Margin</label><strong>${c.revenue?(c.gross/c.revenue*100).toFixed(1):0}%</strong></div><div class=\"card metric\"><label>Net Margin</label><strong>${c.revenue?(c.net/c.revenue*100).toFixed(1):0}%</strong></div></div><div class=\"grid g2 section\"><div class=\"card\"><div class=\"section-head\"><h2>Financial Snapshot</h2></div><p>Paid: <b>${money(c.paid)}</b></p><p>Receivables: <b>${money(c.receivables)}</b></p><p>Overdue: <b>${money(c.overdue)}</b></p><p>Expenses: <b>${money(c.exp)}</b></p><p>Inventory: <b>${money(c.stock)}</b></p></div><div class=\"card\"><div class=\"section-head\"><h2>Inventory Watch</h2></div>${top.length?top.map(p=>`<div style=\"margin:10px 0\"><div style=\"display:flex;justify-content:space-between\"><span>${esc(p.name)}</span><span>${p.qty}</span></div><div class=\"bar\"><i style=\"width:${Math.min(100,Number(p.qty)*8)}%\"></i></div></div>`).join(''):'<div class=\"empty\">No products yet.</div>'}</div></div>`}\nfunction aiPage(){return `<div class=\"page-title\"><div><h1>HAJREEN AI CEO</h1><p>Ask the business intelligence layer about the data currently recorded.</p></div><span class=\"tag\">SERVER-SIDE AI</span></div><div class=\"ai\"><div class=\"card ai-main\"><div id=\"aiLog\" class=\"ai-log\"><div class=\"msg ai\">I am ready. Ask about revenue, profit, stock, customers, receivables, wholesale, marketing, expenses or the next actions for HAJREEN.</div></div><div class=\"ai-input\"><textarea id=\"aiQuestion\" placeholder=\"Example: What are the three biggest risks in my business right now?\"></textarea><button class=\"btn gold\" onclick=\"askAI()\">Ask CEO</button></div></div><div class=\"card\"><h3 style=\"margin-top:0\">CEO lenses</h3><div class=\"form\"><button class=\"btn\" onclick=\"askPreset('Give me a CEO briefing of HAJREEN using only the recorded data.')\">CEO briefing</button><button class=\"btn\" onclick=\"askPreset('Analyze profitability and explain what is driving gross and net profit.')\">Profit intelligence</button><button class=\"btn\" onclick=\"askPreset('Analyze stock levels and identify inventory risks and opportunities.')\">Stock intelligence</button><button class=\"btn\" onclick=\"askPreset('Analyze customers, receivables and overdue balances.')\">Customer & credit</button><button class=\"btn\" onclick=\"askPreset('Analyze wholesale pipeline and suggest practical follow-up priorities.')\">Wholesale</button><button class=\"btn\" onclick=\"askPreset('Analyze marketing performance and ROI from the recorded campaigns.')\">Marketing</button></div></div></div>`}\nfunction settingsPage(){return `<div class='page-title'><div><h1>System</h1><p>Cloud status, data controls, security and business intelligence alerts.</p></div></div><div class='grid g2'><div class='card'><h3>Connection</h3><p>Supabase: <b>${cloudReady?'Connected':'Not connected'}</b></p><p>Session: <b>${session?'Authenticated':'Guest'}</b></p><p>AI: <b>Server route configured</b></p><button class='btn' onclick='syncCloud()'>Sync now</button></div><div class='card'><h3>Customer Follow-up Intelligence</h3><p class='muted'>Customer Pulse learns each customer's actual buying interval. It does not use one fixed reminder period for everyone.</p><div class='security-list'><div class='security-row'><span>Customer Pulse</span><label><input id='setPulse' type='checkbox' ${data.settings.customerPulse!==false?'checked':''} onchange='saveSettings()'> Enabled</label></div><div class='security-row'><span>Message alerts</span><label><input id='setMsg' type='checkbox' ${data.settings.messageAlerts!==false?'checked':''} onchange='saveSettings()'> Enabled</label></div><div class='security-row'><span>Business time zone</span><b class='secure-blue'>Africa/Dar_es_Salaam</b></div></div><p class='muted' style='margin-top:10px'>Every alert is routed into <b>Messages</b> with date, month, year and time.</p></div><div class='card'><h3>Data controls</h3><div class='actions'><button class='btn' onclick='exportBackup()'>Export JSON</button><button class='btn' onclick=\"document.getElementById('importFile').click()\">Import JSON</button><input id='importFile' class='hidden' type='file' accept='application/json' onchange='importBackup(event)'><button class='btn danger' onclick='resetData()'>Reset local data</button></div><p class='muted' style='margin-top:15px'>Reset local data does not delete cloud data.</p></div><div class='card'><h3>Production checklist</h3><div class='alert ok'>OpenAI key stays on the server.</div><div class='alert ok'>Supabase secret key stays on the server.</div><div class='alert ok'>Browser uses publishable key only.</div><div class='alert'>Customer, payment, stock and wholesale alerts appear in Messages.</div></div><div class='card'><h3>Account</h3><p class='muted'>${esc(session?.user?.email||'')}</p><button class='btn' onclick='logout()'>Secure logout</button></div></div>`}\nfunction saveSettings(){data.settings.customerPulse=!!document.getElementById('setPulse')?.checked;data.settings.messageAlerts=!!document.getElementById('setMsg')?.checked;saveLocal();saveCloud();refreshBusinessMessages();navRender();renderPage();toast('Settings updated')}\nfunction customerName(id){return data.customers.find(c=>c.id===id)?.name||'Walk-in customer'} function saleOrder(id){return data.sales.find(s=>s.id===id)?.orderNo||'—'}\nfunction openModal(id){document.getElementById(id).classList.remove('hidden')} function closeModal(id){document.getElementById(id).classList.add('hidden')}\nfunction modal(title,body){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;openModal('formModal')}\nfunction openProduct(){modal('Add product',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addProduct()\"><div class=\"field\"><label>Product name</label><input id=\"pName\" required></div><div class=\"field\"><label>SKU</label><input id=\"pSku\" required></div><div class=\"field\"><label>Category</label><input id=\"pCat\" placeholder=\"Lace\"></div><div class=\"field\"><label>Quantity</label><input id=\"pQty\" type=\"number\" min=\"0\" value=\"0\"></div><div class=\"field\"><label>Cost price</label><input id=\"pCost\" type=\"number\" min=\"0\" value=\"0\"></div><div class=\"field\"><label>Retail price</label><input id=\"pPrice\" type=\"number\" min=\"0\" value=\"0\"></div><div class=\"field\"><label>Wholesale price</label><input id=\"pWhole\" type=\"number\" min=\"0\" value=\"0\"></div><div class=\"field\"><label>Low stock threshold</label><input id=\"pLow\" type=\"number\" min=\"0\" value=\"3\"></div><div class=\"actions\"><button class=\"btn gold\">Save product</button></div></form>`)}\nfunction addProduct(){const p={id:uid('prd'),name:v('pName'),sku:v('pSku'),category:v('pCat'),qty:+v('pQty'),cost:+v('pCost'),price:+v('pPrice'),wholesale:+v('pWhole'),low:+v('pLow')};data.products.push(p);data.stockMovements.push({id:uid('mov'),productId:p.id,type:'OPENING',qty:p.qty,date:today()});commit('Product added');closeModal('formModal')}\nfunction openCustomer(){modal('Add customer',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addCustomer()\"><div class=\"field\"><label>Full name / business</label><input id=\"cName\" required></div><div class=\"field\"><label>Phone / WhatsApp</label><input id=\"cPhone\"></div><div class=\"field\"><label>Customer type</label><select id=\"cType\"><option>Retail</option><option>Wholesale</option><option>Distributor</option><option>VIP</option></select></div><div class=\"field\"><label>Location</label><input id=\"cLoc\"></div><div class=\"field\" style=\"grid-column:1/-1\"><label>Notes</label><textarea id=\"cNotes\"></textarea></div><button class=\"btn gold\">Save customer</button></form>`)}\nfunction addCustomer(){data.customers.push({id:uid('cus'),name:v('cName'),phone:v('cPhone'),type:v('cType'),location:v('cLoc'),notes:v('cNotes'),createdAt:new Date().toISOString()});commit('Customer added');closeModal('formModal')}\nfunction openSale(){if(!data.products.length){toast('Add at least one product first.');return}modal('New Sale',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addSale()\"><div class=\"field\"><label>Customer</label><select id=\"sCustomer\"><option value=\"\">Walk-in customer</option>${data.customers.map(c=>`<option value=\"${c.id}\">${esc(c.name)}</option>`).join('')}</select></div><div class=\"field\"><label>Sale date</label><input id=\"sDate\" type=\"datetime-local\" value=\"${new Date().toISOString().slice(0,16)}\"></div><div class=\"field\" style=\"grid-column:1/-1\"><label>Product</label><select id=\"sProduct\" onchange=\"saleRecalc()\">${data.products.map(p=>`<option value=\"${p.id}\">${esc(p.name)} — ${money(p.price)} · stock ${p.qty}</option>`).join('')}</select></div><div class=\"field\"><label>Quantity</label><input id=\"sQty\" type=\"number\" min=\"1\" value=\"1\" oninput=\"saleRecalc()\"></div><div class=\"field\"><label>Selling price / unit</label><input id=\"sPrice\" type=\"number\" min=\"0\" value=\"${data.products[0]?.price||0}\" oninput=\"saleRecalc()\"></div><div class=\"field\"><label>Discount</label><input id=\"sDiscount\" type=\"number\" min=\"0\" value=\"0\" oninput=\"saleRecalc()\"></div><div class=\"field\"><label>Amount paid</label><input id=\"sPaid\" type=\"number\" min=\"0\" value=\"0\" oninput=\"saleRecalc()\"></div><div class=\"field\"><label>Payment method</label><select id=\"sMethod\"><option>Cash</option><option>Bank</option><option>Mobile Money</option></select></div><div class=\"field\"><label>Due date</label><input id=\"sDue\" type=\"date\" value=\"${today()}\"></div><div style=\"grid-column:1/-1\" class=\"sale-summary\"><div class=\"mini\"><small>Total</small><b id=\"saleTotal\">TSh 0</b></div><div class=\"mini\"><small>Balance</small><b id=\"saleBalance\">TSh 0</b></div><div class=\"mini\"><small>Stock after sale</small><b id=\"saleStock\">0</b></div></div><div class=\"field\" style=\"grid-column:1/-1\"><label>Notes</label><textarea id=\"sNotes\"></textarea></div><button class=\"btn gold\">Save sale</button></form>`);saleRecalc()}\nfunction saleRecalc(){const p=data.products.find(x=>x.id===v('sProduct'));if(!p)return;const qty=Math.max(0,+v('sQty')),price=Math.max(0,+v('sPrice')),discount=Math.max(0,+v('sDiscount')),paid=Math.max(0,+v('sPaid'));const total=Math.max(0,qty*price-discount);const bal=Math.max(0,total-paid);const st=document.getElementById('saleTotal'),sb=document.getElementById('saleBalance'),ss=document.getElementById('saleStock');if(st)st.textContent=money(total);if(sb)sb.textContent=money(bal);if(ss)ss.textContent=Math.max(0,Number(p.qty)-qty)}\nfunction addSale(){const p=data.products.find(x=>x.id===v('sProduct'));const qty=+v('sQty'),price=+v('sPrice'),discount=+v('sDiscount');if(!p||qty<1||p.qty<qty){toast('Insufficient stock.');return}const total=Math.max(0,qty*price-discount),paid=Math.max(0,Math.min(+v('sPaid'),total));const createdAt=new Date(v('sDate')||new Date()).toISOString();const s={id:uid('sal'),orderNo:'HJ-'+Date.now().toString().slice(-7),date:createdAt.slice(0,10),createdAt,customerId:v('sCustomer'),dueDate:v('sDue'),notes:v('sNotes'),total,costTotal:qty*p.cost,discount,items:[{productId:p.id,qty,price,cost:p.cost}]};p.qty-=qty;data.sales.push(s);data.stockMovements.push({id:uid('mov'),productId:p.id,type:'SALE',qty:-qty,date:s.date,createdAt,saleId:s.id});if(paid>0)data.payments.push({id:uid('pay'),saleId:s.id,customerId:s.customerId,amount:paid,method:v('sMethod'),date:s.date,createdAt,reference:'',receiver:'',notes:'Initial payment'});commit('Sale recorded');closeModal('formModal')}\n\nfunction openPayment(saleId=''){const sale=saleId||data.sales.find(s=>Number(s.total)>sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount));modal('Record payment',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addPayment()\"><div class=\"field\" style=\"grid-column:1/-1\"><label>Order</label><select id=\"paySale\" onchange=\"syncPayCustomer()\"><option value=\"\">Select order</option>${data.sales.filter(s=>Number(s.total)>sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount)).map(s=>`<option value=\"${s.id}\" ${s.id===sale?'selected':''}>${esc(s.orderNo)} — ${esc(customerName(s.customerId))} — balance ${money(Number(s.total)-sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount))}</option>`).join('')}</select></div><div class=\"field\"><label>Amount</label><input id=\"payAmount\" type=\"number\" min=\"1\" required></div><div class=\"field\"><label>Date</label><input id=\"payDate\" type=\"date\" value=\"${today()}\"></div><div class=\"field\"><label>Method</label><select id=\"payMethod\" onchange=\"paymentFields()\"><option>Cash</option><option>Bank</option><option>Mobile Money</option></select></div><div id=\"paymentExtra\" class=\"field\"><label>Received by</label><input id=\"payReceiver\" placeholder=\"Name\"></div><div class=\"field\"><label>Reference</label><input id=\"payRef\" placeholder=\"Transaction / receipt number\"></div><div class=\"field\" style=\"grid-column:1/-1\"><label>Notes</label><textarea id=\"payNotes\"></textarea></div><button class=\"btn gold\">Save payment</button></form>`)}\nfunction paymentFields(){const m=v('payMethod');document.getElementById('paymentExtra').innerHTML=m==='Bank'?'<label>Bank / merchant</label><input id=\"payReceiver\" placeholder=\"Bank or account name\">':m==='Mobile Money'?'<label>Network / sender</label><input id=\"payReceiver\" placeholder=\"M-Pesa / Airtel / Mixx / HaloPesa + sender\">':'<label>Received by</label><input id=\"payReceiver\" placeholder=\"Name\">'}\nfunction syncPayCustomer(){}\nfunction addPayment(){const s=data.sales.find(x=>x.id===v('paySale'));if(!s){toast('Select an order.');return}const existing=sum(data.payments.filter(p=>p.saleId===s.id),p=>p.amount),bal=Number(s.total)-existing,amt=+v('payAmount');if(amt<=0||amt>bal){toast('Payment exceeds the outstanding balance.');return}data.payments.push({id:uid('pay'),saleId:s.id,customerId:s.customerId,amount:amt,method:v('payMethod'),date:v('payDate'),createdAt:new Date().toISOString(),reference:v('payRef'),receiver:v('payReceiver'),notes:v('payNotes')});commit('Payment recorded');closeModal('formModal')}\nfunction openExpense(){modal('Add expense',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addExpense()\"><div class=\"field\"><label>Category</label><input id=\"eCat\" placeholder=\"Transport, rent, marketing...\"></div><div class=\"field\"><label>Amount</label><input id=\"eAmt\" type=\"number\" min=\"0\" required></div><div class=\"field\"><label>Date</label><input id=\"eDate\" type=\"date\" value=\"${today()}\"></div><div class=\"field\"><label>Method</label><select id=\"eMethod\"><option>Cash</option><option>Bank</option><option>Mobile Money</option></select></div><div class=\"field\"><label>Vendor</label><input id=\"eVendor\"></div><div class=\"field\"><label>Notes</label><input id=\"eNotes\"></div><button class=\"btn gold\">Save expense</button></form>`)}\nfunction addExpense(){data.expenses.push({id:uid('exp'),category:v('eCat'),amount:+v('eAmt'),date:v('eDate'),method:v('eMethod'),vendor:v('eVendor'),notes:v('eNotes')});commit('Expense added');closeModal('formModal')}\nfunction openWholesale(){modal('Wholesale opportunity',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addWholesale()\"><div class=\"field\"><label>Business / customer</label><input id=\"wName\" required></div><div class=\"field\"><label>Phone</label><input id=\"wPhone\"></div><div class=\"field\"><label>Stage</label><select id=\"wStage\"><option>New</option><option>Contacted</option><option>Qualified</option><option>Proposal</option><option>Won</option><option>Lost</option></select></div><div class=\"field\"><label>Expected value</label><input id=\"wExpected\" type=\"number\" min=\"0\"></div><div class=\"field\"><label>Follow-up</label><input id=\"wFollow\" type=\"date\"></div><div class=\"field\"><label>Notes</label><input id=\"wNotes\"></div><button class=\"btn gold\">Save opportunity</button></form>`)}\nfunction addWholesale(){data.wholesale.push({id:uid('wh'),name:v('wName'),phone:v('wPhone'),stage:v('wStage'),expected:+v('wExpected'),followUp:v('wFollow'),notes:v('wNotes')});commit('Wholesale opportunity added');closeModal('formModal')}\nfunction openMarketing(){modal('Marketing campaign',`<form class=\"form g2\" onsubmit=\"event.preventDefault();addMarketing()\"><div class=\"field\"><label>Campaign</label><input id=\"mName\" required></div><div class=\"field\"><label>Channel</label><input id=\"mChannel\" placeholder=\"Instagram, TikTok, WhatsApp...\"></div><div class=\"field\"><label>Spend</label><input id=\"mSpend\" type=\"number\" min=\"0\"></div><div class=\"field\"><label>Leads</label><input id=\"mLeads\" type=\"number\" min=\"0\"></div><div class=\"field\"><label>Attributed sales value</label><input id=\"mSales\" type=\"number\" min=\"0\"></div><button class=\"btn gold\">Save campaign</button></form>`)}\nfunction addMarketing(){data.marketing.push({id:uid('mkt'),name:v('mName'),channel:v('mChannel'),spend:+v('mSpend'),leads:+v('mLeads'),salesValue:+v('mSales')});commit('Campaign added');closeModal('formModal')}\nfunction viewCustomer(id){const c=data.customers.find(x=>x.id===id);const ss=data.sales.filter(s=>s.customerId===id),pp=data.payments.filter(p=>p.customerId===id);modal('Customer 360',`<div class=\"grid g3\"><div class=\"card metric\"><label>Customer</label><strong style=\"font-size:18px\">${esc(c.name)}</strong><span>${esc(c.type||'Retail')}</span></div><div class=\"card metric\"><label>Total orders</label><strong>${ss.length}</strong></div><div class=\"card metric\"><label>Outstanding</label><strong>${money(sum(ss,s=>Number(s.total)-sum(pp.filter(p=>p.saleId===s.id),p=>p.amount)))}</strong></div></div><div class=\"section\"><p><b>Phone:</b> ${esc(c.phone||'—')} &nbsp; <b>Location:</b> ${esc(c.location||'—')}</p><p class=\"muted\">${esc(c.notes||'')}</p><div class=\"table-wrap\"><table class=\"table\"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th></tr></thead><tbody>${ss.map(s=>{const paid=sum(pp.filter(p=>p.saleId===s.id),p=>p.amount);return `<tr><td>${esc(s.orderNo)}</td><td>${fmtDateTime(s.createdAt||s.date)}</td><td>${money(s.total)}</td><td>${money(paid)}</td><td>${money(Math.max(0,s.total-paid))}</td></tr>`}).join('')||'<tr><td colspan=\"5\" class=\"empty\">No orders.</td></tr>'}</tbody></table></div></div>`)}\nfunction v(id){return document.getElementById(id)?.value?.trim()||''}\nasync function commit(msg){data.activity.push({id:uid('act'),date:new Date().toISOString(),action:msg});saveLocal();renderPage();await saveCloud();toast(msg)}\nasync function loadConfig(){try{const r=await fetch('/api/config');const c=await r.json();if(c.supabaseUrl&&c.supabasePublishableKey){sb=window.supabase.createClient(c.supabaseUrl,c.supabasePublishableKey);const {data:s}=await sb.auth.getSession();session=s.session;if(session){showApp();await syncCloud(false)}else showLogin();sb.auth.onAuthStateChange(async(_e,sess)=>{session=sess;if(sess){showApp();await syncCloud(false)}else showLogin()})}else showApp()}catch(e){showApp();toast('Running in local mode — server config unavailable.')}}\nfunction showLogin(){document.getElementById('loginView').classList.remove('hidden');document.getElementById('app').classList.add('hidden')}\nfunction showApp(){document.getElementById('loginView').classList.add('hidden');document.getElementById('app').classList.remove('hidden');const m=document.getElementById('main');m.innerHTML='<div class=\"card\" style=\"padding:28px;text-align:center;color:#8c969e\">Loading HAJREEN…</div>';try{data=normalizeData(data);navRender();renderPage()}catch(e){console.error('HAJREEN startup render error',e);m.innerHTML='<div class=\"card\" style=\"padding:28px\"><h2 style=\"margin-top:0\">HAJREEN is loading your workspace…</h2><p class=\"muted\">Your session is active. Retrying the business workspace now.</p><button class=\"btn gold\" onclick=\"data=normalizeData(data);navRender();renderPage()\">Open Workspace</button></div>'}}\nfunction setAuthMode(m){authMode=m;document.getElementById('tabLogin').classList.toggle('active',m==='login');document.getElementById('tabSignup').classList.toggle('active',m==='signup');document.getElementById('authBtn').textContent=m==='login'?'Sign in':'Create account';document.getElementById('authMsg').textContent=''}\nfunction togglePassword(){const x=document.getElementById('authPassword');x.type=x.type==='password'?'text':'password'}\nasync function submitAuth(){if(!sb){toast('Supabase is not configured yet.');return}const email=v('authEmail'),password=v('authPassword');if(!email||!password){document.getElementById('authMsg').textContent='Email and password are required.';return}document.getElementById('authBtn').disabled=true;document.getElementById('authMsg').textContent='Working...';let res=authMode==='login'?await sb.auth.signInWithPassword({email,password}):await sb.auth.signUp({email,password});document.getElementById('authBtn').disabled=false;if(res.error){document.getElementById('authMsg').textContent=res.error.message;return}if(authMode==='signup'&&!res.data.session){document.getElementById('authMsg').textContent='Account created. Check your email if confirmation is enabled.'}else{session=res.data.session;showApp();await syncCloud(false)}}\nasync function resetPassword(){if(!sb){toast('Supabase is not configured.');return}const email=v('authEmail');if(!email){toast('Enter your email first.');return}const r=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin});toast(r.error?r.error.message:'Password reset email sent.')}async function logout(){if(sb)await sb.auth.signOut();session=null;showLogin()}\nasync function syncCloud(show=true){if(!session){cloudReady=false;document.getElementById('cloudPill').textContent='LOCAL MODE';return}try{const token=session.access_token;const r=await fetch('/api/data',{headers:{Authorization:'Bearer '+token}});if(r.ok){const j=await r.json();if(j.data&&Object.keys(j.data).length){data=normalizeData(j.data);saveLocal();try{renderPage()}catch(e){console.error('Cloud render error',e)}}else{data=normalizeData(data)}cloudReady=true;document.getElementById('cloudPill').textContent='CLOUD CONNECTED';if(show)toast('Cloud synced')}else{cloudReady=false;document.getElementById('cloudPill').textContent='CLOUD SETUP NEEDED'}}catch(e){cloudReady=false;document.getElementById('cloudPill').textContent='OFFLINE'}}\nasync function saveCloud(){if(!session)return false;try{const r=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify(data)});if(r.ok){cloudReady=true;document.getElementById('cloudPill').textContent='CLOUD CONNECTED';return true}return false}catch{return false}}\nasync function askAI(){const q=document.getElementById('aiQuestion').value.trim();if(!q)return;document.getElementById('aiQuestion').value='';const log=document.getElementById('aiLog');log.innerHTML+=`<div class=\"msg user\">${esc(q)}</div>`;log.innerHTML+=`<div class=\"msg ai\" id=\"thinking\">Analyzing current business data...</div>`;log.scrollTop=log.scrollHeight;try{const r=await fetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({question:q,businessData:data})});const j=await r.json();document.getElementById('thinking').textContent=j.answer||j.error||'No response.'}catch(e){document.getElementById('thinking').textContent='AI request failed. Check the server OpenAI configuration.'}}\nfunction askPreset(q){go('ai');setTimeout(()=>{document.getElementById('aiQuestion').value=q;askAI()},80)}\nfunction exportBackup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='hajreen-v16-backup-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}\nfunction importBackup(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{data={...clone(EMPTY),...JSON.parse(r.result)};saveLocal();renderPage();toast('Backup imported')}catch{toast('Invalid backup file')}};r.readAsText(f)}\nfunction resetData(){if(!confirm('Reset local data? This cannot be undone locally.'))return;data=clone(EMPTY);saveLocal();renderPage();toast('Local data reset')}\nloadConfig();\n</script></body></html>";
function send(res,status,body,type='application/json'){res.writeHead(status,{'Content-Type':type,'Cache-Control':'no-store'});res.end(typeof body==='string'?body:JSON.stringify(body));}
function bearer(req){const h=req.headers.authorization||'';return h.startsWith('Bearer ')?h.slice(7):''}
async function body(req){let s='';for await(const c of req)s+=c;if(!s)return{};try{return JSON.parse(s)}catch{return{}}}
async function userFromToken(token){if(!token||!SUPABASE_URL||!SUPABASE_PUBLISHABLE_KEY)return null;const r=await fetch(SUPABASE_URL+'/auth/v1/user',{headers:{apikey:SUPABASE_PUBLISHABLE_KEY,Authorization:'Bearer '+token}});if(!r.ok)return null;return await r.json()}
async function sbFetch(path,opts={}){const h={apikey:SUPABASE_SECRET_KEY,Authorization:'Bearer '+SUPABASE_SECRET_KEY,'Content-Type':'application/json',...(opts.headers||{})};return fetch(SUPABASE_URL+path,{...opts,headers:h})}
const setupSQL=`create table if not exists public.app_data (user_id uuid primary key references auth.users(id) on delete cascade, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
alter table public.app_data enable row level security;
drop policy if exists "Users can read own app data" on public.app_data;
create policy "Users can read own app data" on public.app_data for select to authenticated using (auth.uid() = user_id);
drop policy if exists "Users can insert own app data" on public.app_data;
create policy "Users can insert own app data" on public.app_data for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "Users can update own app data" on public.app_data;
create policy "Users can update own app data" on public.app_data for update to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
create index if not exists app_data_updated_at_idx on public.app_data(updated_at desc);`;
const server=http.createServer(async(req,res)=>{
 try{
  const u=new URL(req.url,'http://localhost');
  if(req.method==='GET'&&u.pathname==='/'){return send(res,200,HTML,'text/html; charset=utf-8')}
  if(req.method==='GET'&&u.pathname==='/api/config')return send(res,200,{supabaseUrl:SUPABASE_URL,supabasePublishableKey:SUPABASE_PUBLISHABLE_KEY,model:OPENAI_MODEL});
  if(req.method==='GET'&&u.pathname==='/api/health')return send(res,200,{ok:true,service:'HAJREEN',supabase:!!SUPABASE_URL,openai:!!OPENAI_KEY,model:OPENAI_MODEL});
  if(req.method==='GET'&&u.pathname==='/api/setup/sql')return send(res,200,setupSQL,'text/plain; charset=utf-8');
  if(req.method==='GET'&&u.pathname==='/api/supabase/health'){if(!SUPABASE_SECRET_KEY)return send(res,200,{ok:false,reason:'missing secret key'});const r=await sbFetch('/rest/v1/app_data?select=user_id&limit=1');return send(res,200,{ok:r.ok,status:r.status})}
  if(req.method==='GET'&&u.pathname==='/api/data'){
   const user=await userFromToken(bearer(req));if(!user)return send(res,401,{error:'Unauthorized'});if(!SUPABASE_SECRET_KEY)return send(res,503,{error:'SUPABASE_SECRET_KEY missing'});
   const r=await sbFetch('/rest/v1/app_data?user_id=eq.'+encodeURIComponent(user.id)+'&select=data,updated_at&limit=1');const t=await r.text();if(!r.ok)return send(res,r.status,{error:t});let rows=[];try{rows=JSON.parse(t)}catch{}return send(res,200,{data:rows[0]?.data||{},updated_at:rows[0]?.updated_at||null});
  }
  if(req.method==='PUT'&&u.pathname==='/api/data'){
   const user=await userFromToken(bearer(req));if(!user)return send(res,401,{error:'Unauthorized'});if(!SUPABASE_SECRET_KEY)return send(res,503,{error:'SUPABASE_SECRET_KEY missing'});const b=await body(req);
   const r=await sbFetch('/rest/v1/app_data',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:user.id,data:b||{},updated_at:new Date().toISOString()})});const t=await r.text();if(!r.ok)return send(res,r.status,{error:t});return send(res,200,{ok:true});
  }
  if(req.method==='POST'&&u.pathname==='/api/ai/analyze'){
   if(!OPENAI_KEY)return send(res,503,{error:'OPENAI_API_KEY is not configured.'});const b=await body(req);const q=String(b.question||'').slice(0,5000);const d=b.businessData||{};
   const system='You are HAJREEN AI CEO, a serious business intelligence analyst. Analyze ONLY the supplied HAJREEN business data. Never invent numbers. Distinguish recorded facts from estimates. Answer in clear Swahili at CEO level. Structure: STATUS, FINDINGS, RISKS, OPPORTUNITIES, ACTIONS. Focus on revenue, gross profit, net profit, expenses, stock, customers, receivables, payments, wholesale, marketing and execution.';
   const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+OPENAI_KEY},body:JSON.stringify({model:OPENAI_MODEL,input:system+'\n\nBUSINESS DATA:\n'+JSON.stringify(d)+'\n\nCEO QUESTION:\n'+q,max_output_tokens:2200})});const j=await r.json();if(!r.ok)return send(res,r.status,{error:j.error?.message||'OpenAI request failed'});let answer=j.output_text||'';if(!answer&&Array.isArray(j.output))answer=j.output.flatMap(x=>x.content||[]).map(x=>x.text||'').join('');return send(res,200,{answer:answer||'No answer returned.'});
  }
  return send(res,404,{error:'Not found'});
 }catch(e){return send(res,500,{error:e.message||'Server error'})}
});
server.listen(PORT,()=>console.log('HAJREEN listening on port '+PORT));
